interactions.sample_code:
x = pivot()
i = p - 1
for (j = p; j < r; j = j + 1) {
  if (lessOrEqual(j)) {
    i = i + 1
    swap(i, j)
  }
}
return i + 1

interactions.buggy_code:
x = pivot()
i = p - 1
for (j = p; j < r; j = j + 1) {
  if (lessOrEqual(j)) {
    swap(i + 1, j)   // BUG: i is never advanced, so the ≤ x boundary stalls and small elements land in the wrong region
  }
}
return i + 1

